WITH filtered AS (SELECT *, DATE_SUB(sale_date, 57) AS sale_date_minus_57d FROM store_sales WHERE sale_date > DATE '2023-08-26' AND store_id IN (4, 5, 6)) SELECT DATE_TRUNC('YEAR', sale_date) AS year_start, CASE WHEN units >= 40 THEN 'LARGE' ELSE 'SMALL' END AS units_tier, BIT_AND(units) AS units_bit_and, ROUND(AVG(revenue), 2) AS avg_revenue, APPROX_PERCENTILE(units, 0.95) AS units_p95, RANK() OVER (PARTITION BY DATE_TRUNC('YEAR', sale_date) ORDER BY ROUND(AVG(revenue), 2) DESC) AS avg_revenue_rank FROM filtered GROUP BY 1, 2 HAVING BIT_AND(units) < 1 ORDER BY units_tier NULLS LAST
